using Godot;
using System;
using System.Collections.Generic;
namespace MySim {
// Diagnostic-only single-surface candidate. Exact source vertices are reused. Only interior
// diagonals of an eligible planar island may change; every island/inter-island boundary edge stays.
public static class PlanarRoadRetriangulationCandidate {
 const double ExactPlaneTolerance=.000001;
 public sealed class Result {
  public double PlaneTolerance,MaximumSupportHeightErrorBound;public StaticBody3D Body;public int InputTriangles,ChangedIslands,ChangedSourceTriangles,OutputTriangles,RetainedIslands,RemovedInternalEdges;public double MaximumPlaneError,MaximumAreaError;public readonly List<object> Islands=new();
  public object Evidence()=>new{InputTriangles,ChangedIslands,ChangedSourceTriangles,OutputTriangles,RetainedIslands,RemovedInternalEdges,MaximumPlaneError,MaximumAreaError,Islands,planeToleranceMetres=PlaneTolerance,MaximumSupportHeightErrorBound,oneConcaveShape=Body.GetChildCount()==1,scope="Exact source vertices and all island boundary/inter-island edges retained; only coplanar interior diagonals may change. No thickness, side/bottom faces, holes or area filling. Explicit planar numeric bound recorded above; nonzero error is a bounded support approximation, not exact source surface. No collision/race acceptance implied."};
 }
 readonly struct Edge:IEquatable<Edge>{public readonly int A,B;public Edge(int a,int b){A=Math.Min(a,b);B=Math.Max(a,b);}public bool Equals(Edge e)=>A==e.A&&B==e.B;public override bool Equals(object o)=>o is Edge e&&Equals(e);public override int GetHashCode()=>HashCode.Combine(A,B);}
 static double Cross(Vector3 a,Vector3 b,Vector3 c)=>(double)(b.X-a.X)*(c.Z-a.Z)-(double)(b.Z-a.Z)*(c.X-a.X);
 static double Area(List<int[]> faces,List<Vector3> vertices){double sum=0;foreach(var f in faces)sum+=Math.Abs(Cross(vertices[f[0]],vertices[f[1]],vertices[f[2]]))*.5;return sum;}
 static double PlaneError(Vector3 a,Vector3 b,Vector3 c,Vector3 p){double x1=(double)b.X-a.X,y1=(double)b.Y-a.Y,z1=(double)b.Z-a.Z,x2=(double)c.X-a.X,y2=(double)c.Y-a.Y,z2=(double)c.Z-a.Z;double nx=y1*z2-z1*y2,ny=z1*x2-x1*z2,nz=x1*y2-y1*x2;double length=Math.Sqrt(nx*nx+ny*ny+nz*nz);return length>1e-12?Math.Abs(nx*((double)p.X-a.X)+ny*((double)p.Y-a.Y)+nz*((double)p.Z-a.Z))/length:double.PositiveInfinity;}
 static Dictionary<Edge,int> Edges(List<int[]> faces){var edges=new Dictionary<Edge,int>();foreach(var f in faces)for(int j=0;j<3;j++){var edge=new Edge(f[j],f[(j+1)%3]);edges.TryGetValue(edge,out int n);edges[edge]=n+1;}return edges;}
 static bool Contains(Vector3 a,Vector3 b,Vector3 c,Vector3 p,double sign){const double epsilon=1e-10;return Cross(a,b,p)*sign>=-epsilon&&Cross(b,c,p)*sign>=-epsilon&&Cross(c,a,p)*sign>=-epsilon;}
 public static Result Build(Vector3[] source,double planeTolerance=ExactPlaneTolerance){
  if(planeTolerance!=ExactPlaneTolerance&&planeTolerance!=.0001)throw new ArgumentOutOfRangeException(nameof(planeTolerance));
  if(source==null||source.Length%3!=0)throw new ArgumentException("Incomplete road triangles");var result=new Result{InputTriangles=source.Length/3,PlaneTolerance=planeTolerance};var vertices=new List<Vector3>();var ids=new Dictionary<Vector3,int>();var faces=new List<int[]>();foreach(var p in source){if(!p.IsFinite())throw new Exception("Nonfinite source vertex");if(!ids.ContainsKey(p)){ids[p]=vertices.Count;vertices.Add(p);}}
  for(int i=0;i<source.Length;i+=3)faces.Add(new[]{ids[source[i]],ids[source[i+1]],ids[source[i+2]]});var edgeFaces=new Dictionary<Edge,List<int>>();for(int i=0;i<faces.Count;i++)for(int j=0;j<3;j++){var edge=new Edge(faces[i][j],faces[i][(j+1)%3]);if(!edgeFaces.TryGetValue(edge,out var list)){list=new();edgeFaces[edge]=list;}list.Add(i);}
  var neighbours=new List<int>[faces.Count];for(int i=0;i<faces.Count;i++)neighbours[i]=new();foreach(var list in edgeFaces.Values)if(list.Count==2){var a=faces[list[0]];var b=faces[list[1]];bool planar=true;foreach(int id in b)if(PlaneError(vertices[a[0]],vertices[a[1]],vertices[a[2]],vertices[id])>planeTolerance)planar=false;if(Cross(vertices[a[0]],vertices[a[1]],vertices[a[2]])*Cross(vertices[b[0]],vertices[b[1]],vertices[b[2]])<=0)planar=false;if(planar){neighbours[list[0]].Add(list[1]);neighbours[list[1]].Add(list[0]);}}
  var replacements=new Dictionary<int,List<int[]>>();var changedFaces=new HashSet<int>();var output=new List<int[]>();var visited=new bool[faces.Count];for(int seed=0;seed<faces.Count;seed++){
   if(visited[seed])continue;var group=new List<int>();var stack=new Stack<int>();stack.Push(seed);visited[seed]=true;while(stack.Count>0){int f=stack.Pop();group.Add(f);foreach(int next in neighbours[f])if(!visited[next]){visited[next]=true;stack.Push(next);}}
   var original=new List<int[]>();foreach(int f in group)original.Add(faces[f]);var edges=Edges(original);var boundaryGraph=new Dictionary<int,List<int>>();bool valid=group.Count>=2;double maxPlane=0;var plane=faces[seed];var unique=new HashSet<int>();foreach(var f in original)foreach(int id in f){unique.Add(id);maxPlane=Math.Max(maxPlane,PlaneError(vertices[plane[0]],vertices[plane[1]],vertices[plane[2]],vertices[id]));}
   var triangleNormal=(vertices[plane[1]]-vertices[plane[0]]).Cross(vertices[plane[2]]-vertices[plane[0]]);double normalY=triangleNormal.LengthSquared()>1e-20f?Math.Abs(triangleNormal.Y)/triangleNormal.Length():0;double heightErrorBound=normalY>0?2*maxPlane/normalY:double.PositiveInfinity;if(maxPlane>planeTolerance||normalY<.8||heightErrorBound>(planeTolerance==ExactPlaneTolerance?.0001:.00025))valid=false;foreach(var entry in edges){if(entry.Value>2)valid=false;if(entry.Value!=1)continue;foreach(var pair in new[]{(entry.Key.A,entry.Key.B),(entry.Key.B,entry.Key.A)}){if(!boundaryGraph.TryGetValue(pair.Item1,out var list)){list=new();boundaryGraph[pair.Item1]=list;}list.Add(pair.Item2);}}
   foreach(var list in boundaryGraph.Values)if(list.Count!=2)valid=false;var boundary=new List<int>();if(valid&&boundaryGraph.Count>=3){int start=int.MaxValue;foreach(int id in boundaryGraph.Keys)start=Math.Min(start,id);int previous=-1,current=start;do{if(boundary.Contains(current)){valid=false;break;}boundary.Add(current);var next=boundaryGraph[current];int choice=next[0]==previous?next[1]:next[0];previous=current;current=choice;}while(current!=start&&boundary.Count<=boundaryGraph.Count);if(boundary.Count!=boundaryGraph.Count||current!=start)valid=false;}else valid=false;
   double signedArea=0;for(int i=0;i<boundary.Count;i++){var a=vertices[boundary[i]];var b=vertices[boundary[(i+1)%boundary.Count]];signedArea+=(double)a.X*b.Z-(double)a.Z*b.X;}double sign=Math.Sign(signedArea);if(sign==0)valid=false;foreach(int id in unique)if(!boundaryGraph.ContainsKey(id))valid=false; // Interior vertices are retained by rejecting this island, never silently dropped.
   for(int i=0;i<boundary.Count&&valid;i++)if(Cross(vertices[boundary[(i+boundary.Count-1)%boundary.Count]],vertices[boundary[i]],vertices[boundary[(i+1)%boundary.Count]])*sign< -1e-10)valid=false;
   var triangulated=new List<int[]>();var polygon=new List<int>(boundary);int iterations=0;while(valid&&polygon.Count>3){bool clipped=false; // reverse scan deliberately chooses a deterministic alternate diagonal.
    for(int i=polygon.Count-1;i>=0;i--){int a=polygon[(i+polygon.Count-1)%polygon.Count],b=polygon[i],c=polygon[(i+1)%polygon.Count];if(Cross(vertices[a],vertices[b],vertices[c])*sign<=1e-10)continue;bool blocked=false;foreach(int p in polygon)if(p!=a&&p!=b&&p!=c&&Contains(vertices[a],vertices[b],vertices[c],vertices[p],sign)){blocked=true;break;}if(blocked)continue;triangulated.Add(new[]{a,b,c});polygon.RemoveAt(i);clipped=true;break;}if(!clipped||++iterations>boundary.Count)valid=false;
   }
   if(valid&&polygon.Count==3&&Math.Abs(Cross(vertices[polygon[0]],vertices[polygon[1]],vertices[polygon[2]]))>1e-10)triangulated.Add(polygon.ToArray());else valid=false;
   // Preserve authored winding, regardless of which boundary direction was traced.
   double originalSign=Math.Sign(Cross(vertices[plane[0]],vertices[plane[1]],vertices[plane[2]]));foreach(var f in triangulated)if(Cross(vertices[f[0]],vertices[f[1]],vertices[f[2]])*originalSign<0)(f[1],f[2])=(f[2],f[1]);
   double originalArea=Area(original,vertices),newArea=Area(triangulated,vertices),areaError=Math.Abs(newArea-originalArea);var newEdges=Edges(triangulated);int removed=0;if(valid){foreach(var e in edges){if(e.Value==1&&(!newEdges.TryGetValue(e.Key,out int n)||n!=1))valid=false;if(e.Value==2&&!newEdges.ContainsKey(e.Key))removed++;}foreach(var e in newEdges)if(e.Value>2||e.Value==1&&(!edges.TryGetValue(e.Key,out int n)||n!=1))valid=false;var outputVertices=new HashSet<int>();foreach(var f in triangulated)foreach(int id in f)outputVertices.Add(id);if(!outputVertices.SetEquals(unique)||areaError>Math.Max(1e-8,originalArea*1e-10)||triangulated.Count!=original.Count)valid=false;}
   int originalInternalEdges=0,replacementInternalEdges=0;foreach(int n in edges.Values)if(n==2)originalInternalEdges++;foreach(int n in newEdges.Values)if(n==2)replacementInternalEdges++;bool changed=valid&&removed>0;result.Islands.Add(new{sourceTriangles=original.Count,vertices=unique.Count,boundaryVertices=boundary.Count,maxPlaneError=double.IsFinite(maxPlane)?(double?)maxPlane:null,maximumSupportHeightErrorBound=double.IsFinite(heightErrorBound)?(double?)heightErrorBound:null,originalProjectedArea=originalArea,generatedProjectedArea=newArea,areaError,boundaryEdgesPreserved=valid,allSourceVerticesPreserved=valid,changed,originalInternalEdges,replacementInternalEdges=changed?replacementInternalEdges:originalInternalEdges,removedInternalEdges=changed?removed:0,exactSurfaceClaim=maxPlane==0,approximationNote="Vertices never move; nonzero numeric planarity error means replacement interior support can differ, so not claimed exact surface"});
   if(changed){replacements[seed]=triangulated;foreach(int face in group)changedFaces.Add(face);result.ChangedIslands++;result.ChangedSourceTriangles+=original.Count;result.RemovedInternalEdges+=removed;result.MaximumPlaneError=Math.Max(result.MaximumPlaneError,maxPlane);result.MaximumSupportHeightErrorBound=Math.Max(result.MaximumSupportHeightErrorBound,heightErrorBound);result.MaximumAreaError=Math.Max(result.MaximumAreaError,areaError);}else{result.RetainedIslands++;}
  }
  for(int i=0;i<faces.Count;i++){if(replacements.TryGetValue(i,out var replacement))output.AddRange(replacement);else if(!changedFaces.Contains(i))output.Add(faces[i]);}
  var rebuilt=new List<Vector3>();foreach(var f in output)foreach(int id in f)rebuilt.Add(vertices[id]);if(rebuilt.Count!=source.Length)throw new Exception("Retriangulation triangle accounting failed");result.OutputTriangles=output.Count;result.Body=new StaticBody3D{Name="DriveSurface",CollisionLayer=1,CollisionMask=4};result.Body.AddChild(new CollisionShape3D{Shape=new ConcavePolygonShape3D{Data=rebuilt.ToArray(),BackfaceCollision=true}});return result;
 }
}
}
